window.docContents[231].resolve({"/#Jakarta-Persistence--3___-Entity-Operations--3___6___-Entity-Instance-Lifecycle--3___6___2___-Entity-Instance-Creation":{"contents":"An instance of an entity class may be created using the new operator. A newly instantiated instance is not considered persistent—​that is, it is not considered to represent a record in the database—​and the new instance is not associated with a persistence context. A new instance is not considered to have a well-defined persistent identity until it is made persistent.\n\n\n\nFormalized SpecificationYou can't create already created entitiesaction Create (e : entity) {\n  require ¬ created e\n  created e := true\n  assert ¬ belongsToContext e\n  assert pid e = noIdentity\n}\n\n\n\n\n","context":"Jakarta Persistence\u00093. Entity Operations\u00093.6. Entity Instance Lifecycle","header":"3.6.2. Entity Instance Creation","id":"/#Jakarta-Persistence--3___-Entity-Operations--3___6___-Entity-Instance-Lifecycle--3___6___2___-Entity-Instance-Creation"}});